parameters.new_string:
import Ajv from 'ajv';
import type {ValidateFunction, ErrorObject} from 'ajv';

// @ts-expect-error Ajv is a class but sometimes imported as a type in NodeNext
const ajv = new Ajv({
  strict: false,
  validateFormats: false,
});

const validatorCache = new WeakMap<object, ValidateFunction>();

/** Executes a tool by name; see specs/hal-engine-tool-input-validation/spec.md */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const definition = this.resolveDefinition(tool.definitionSource);
  const validator = tool.staticValidator ?? this.getValidator(definition.inputSchema, name);

  if (!validator) {
    return {result: `Tool ${name} has an invalid input schema`};
  }

  if (!validator(input)) {
    const errors = validator.errors || [];
    const validationSummary = this.formatAjvErrors(errors);
    const result = `Invalid input for tool ${name}: ${validationSummary}`;
    log.warn('tool', 'validation failed', {name, validationSummary});
    return {result};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);
  const response = normalizeToolResponse(rawResult);
  log.info('tool', 'execution complete', {
    name,
    rawType: typeof rawResult,
    clientMessageCount: response.clientMessages?.length ?? 0,
    clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
    suppressAssistantResponse: response.suppressAssistantResponse ?? false,
  });
  return response;
}

private formatAjvErrors(errors: ErrorObject[]): string {
  return errors
    .map(err => {
      let path = err.instancePath;
      const params = err.params as Record<string, unknown>;
      if (err.keyword === 'required' && typeof params.missingProperty === 'string') {
        const missingProperty = params.missingProperty;
        path = path ? `${path}/${missingProperty}` : missingProperty;
      }
      if (!path || path === '') path = 'input';
      return `${path} ${err.message}`;
    })
    .join(', ');
}

